<?php declare(strict_types=1);
$yearClosingText=static fn(string $text):string=>\Kulturhus\Native\Language\BalanceFilingMessages::text($text,$managerLanguageMessages??[]);
try{$yearClosingReader=new \Kulturhus\Verein\BalanceYearClosingRead($db,(string)$_SESSION['actor']);$yearClosingSaved=$yearClosingReader->get(input($_GET,'balance_year'),input($_GET,'year_closing_sha256'));$yearClosingOriginal=$yearClosingSaved['original'];$yearClosingCurrent=$yearClosingSaved['current'];$yearClosingAt=(new DateTimeImmutable($yearClosingOriginal['review']['at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i');}
catch(DomainException $failure){if(!headers_sent())http_response_code(in_array($failure->getCode(),[403,404,409,422,503],true)?$failure->getCode():422);echo '<p role="alert">'.e($yearClosingText($failure->getMessage())).'</p>';return;}
$yearClosingMoney=static fn(int $cents):string=>number_format($cents/100,2,',','.').' €';
?>
<link rel="stylesheet" href="tax-guided.css?v=3"><div class="content" data-tax-guided>
<div class="page-heading"><h1><?= e($yearClosingText('Gespeicherter ursprünglicher Jahresabschluss')) ?></h1></div><p><?= e((string)$yearClosingSaved['year']) ?></p>
<section class="card" data-annual-closing-original="<?= e($yearClosingSaved['sha256']) ?>"><p role="status"><?= e($yearClosingText('Dieser Jahresabschluss wurde damals festgeschrieben. Das Öffnen bestätigt keinen neuen Abschlussauftrag.')) ?></p>
<dl><dt><?= e($yearClosingText('Festgeschrieben am')) ?></dt><dd><?= e($yearClosingAt) ?></dd><dt><?= e($yearClosingText('Prüfvermerk / Nachweis')) ?></dt><dd><?= e($yearClosingOriginal['review']['note']) ?></dd><dt><?= e($yearClosingText('Jahresergebnis dieses Zahlenstands')) ?></dt><dd><?= e($yearClosingMoney($yearClosingOriginal['calculation']['annual_result_cents'])) ?></dd><dt><?= e($yearClosingText('Vermögen am Jahresende')) ?></dt><dd><?= e($yearClosingMoney($yearClosingOriginal['calculation']['asset_total_cents'])) ?></dd></dl>
<details><summary><?= e($yearClosingText('Damals bestätigte Abschlussprüfung')) ?></summary><ul><?php foreach(['complete'=>'Bilanzjournal vollständig mit Belegen und Bankbeständen abgestimmt.','valuation'=>'Vermögen, Verbindlichkeiten, Rückstellungen und Abschreibungen geprüft.','cutoff'=>'Offene Posten und Rechnungsabgrenzung dem richtigen Jahr zugeordnet.','tax'=>'Steuerliche Behandlung geprüft; benötigte Überleitung gesondert dokumentiert.']as$key=>$label): ?><li><?= e($yearClosingText($label)) ?> · <?= e($yearClosingText(($yearClosingOriginal['review']['checks'][$key]??null)===true?'Im ursprünglichen Formular bestätigt':'Im ursprünglichen Formular nicht bestätigt')) ?></li><?php endforeach ?></ul></details>
<details><summary><?= e($yearClosingText('Damals gespeicherte Buchungen')) ?></summary><?php foreach($yearClosingOriginal['entries']as$yearClosingEntry): ?><article><h2><?= e(implode('.',array_reverse(explode('-',$yearClosingEntry['date']))).' · '.$yearClosingEntry['description']) ?></h2><p><?= e($yearClosingEntry['evidence']) ?></p><?php foreach($yearClosingEntry['lines']as$yearClosingLine): ?><p><?= e($yearClosingOriginal['calculation']['accounts'][$yearClosingLine['account']]['name']) ?> · <?= e($yearClosingText('Soll')) ?> <?= e($yearClosingMoney($yearClosingLine['debit_cents'])) ?> · <?= e($yearClosingText('Haben')) ?> <?= e($yearClosingMoney($yearClosingLine['credit_cents'])) ?></p><?php endforeach ?></article><?php endforeach ?></details></section>
<section class="card" data-annual-closing-current><h2><?= e($yearClosingText('Aktueller Stand des Jahresabschlusses')) ?></h2><p><?= e($yearClosingText($yearClosingCurrent['issues']===[]?'Buchungsstand festgeschrieben':'Aktuellen Jahresabschluss prüfen')) ?></p><p><?= e($yearClosingText('Jahresergebnis dieses Zahlenstands').': '.$yearClosingMoney($yearClosingCurrent['calculation']['annual_result_cents'])) ?></p><?php if($yearClosingCurrent['closed_sha256']!==$yearClosingSaved['sha256']): ?><p><?= e($yearClosingText('Zum ursprünglichen Jahresabschluss besteht eine spätere Berichtigung.')) ?></p><?php endif ?></section>
<p><a class="btn btn-outline" data-annual-closing-current-link href="<?= e(url(['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$yearClosingSaved['year']])) ?>"><?= e($yearClosingText('Aktuellen Jahresstand öffnen')) ?></a></p></div>
